export type Role = "admin" | "member";

export interface User {
  username: string;
  password: string;
  role: Role;
}

export interface AuthOptions {
  users: User[];
  secret: string;
  now?: () => Date;
}

export function createAuthHandler(
  options: AuthOptions,
): (req: Request) => Promise<Response> {
  const { users, secret } = options;
  const now: () => Date = options.now ?? (() => new Date());

  const revoked = new Set<string>();

  let hmacKey: CryptoKey | null = null;
  async function getKey(): Promise<CryptoKey> {
    if (!hmacKey) {
      hmacKey = await crypto.subtle.importKey(
        "raw",
        new TextEncoder().encode(secret),
        { name: "HMAC", hash: "SHA-256" },
        false,
        ["sign", "verify"],
      );
    }
    return hmacKey;
  }

  function b64url(data: ArrayBuffer | Uint8Array): string {
    const bytes = data instanceof Uint8Array ? data : new Uint8Array(data);
    let s = "";
    for (let i = 0; i < bytes.length; i++) {
      s += String.fromCharCode(bytes[i]);
    }
    return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }

  function b64urlDecode(s: string): Uint8Array {
    let str = s.replace(/-/g, "+").replace(/_/g, "/");
    while (str.length % 4) str += "=";
    const bin = atob(str);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  async function sign(msg: string): Promise<string> {
    const key = await getKey();
    const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(msg));
    return b64url(sig);
  }

  async function verify(msg: string, sig: string): Promise<boolean> {
    try {
      const key = await getKey();
      const sigBytes = b64urlDecode(sig);
      return await crypto.subtle.verify("HMAC", key, sigBytes, new TextEncoder().encode(msg));
    } catch {
      return false;
    }
  }

  function json(status: number, body: unknown): Response {
    return new Response(JSON.stringify(body), {
      status,
      headers: { "Content-Type": "application/json; charset=utf-8" },
    });
  }

  async function auth(req: Request): Promise<User | null> {
    const h = req.headers.get("Authorization");
    if (!h || !h.startsWith("Bearer ")) return null;
    const token = h.slice(7);
    if (!token || token.includes(" ")) return null;
    const dot = token.indexOf(".");
    if (dot === -1 || dot === token.length - 1) return null;
    const payloadB64 = token.slice(0, dot);
    const sig = token.slice(dot + 1);
    if (!payloadB64 || !sig) return null;

    const ok = await verify(payloadB64, sig);
    if (!ok) return null;
    if (revoked.has(token)) return null;

    let payload: { u?: string; t?: number; n?: string };
    try {
      const decoded = new TextDecoder().decode(b64urlDecode(payloadB64));
      payload = JSON.parse(decoded);
    } catch {
      return null;
    }

    if (typeof payload.u !== "string" || typeof payload.t !== "number") return null;
    const expires = payload.t + 3_600_000;
    if (now().getTime() >= expires) return null;

    const user = users.find((u) => u.username === payload.u);
    return user ?? null;
  }

  return async (req: Request): Promise<Response> => {
    const url = new URL(req.url);
    const path = url.pathname;
    const method = req.method;

    // POST /login
    if (method === "POST" && path === "/login") {
      let body: unknown;
      try {
        body = await req.json();
      } catch {
        return json(400, { error: "invalid_request" });
      }
      if (body === null || typeof body !== "object" || Array.isArray(body)) {
        return json(400, { error: "invalid_request" });
      }
      const obj = body as Record<string, unknown>;
      const username = obj["username"];
      const password = obj["password"];
      if (typeof username !== "string" || typeof password !== "string") {
        return json(400, { error: "invalid_request" });
      }

      const user = users.find((u) => u.username === username && u.password === password);
      if (!user) {
        return json(401, { error: "invalid_credentials" });
      }

      const t = now();
      const issuedAt = t.getTime();
      const expiresAt = new Date(issuedAt + 3_600_000);
      const nonce = b64url(crypto.getRandomValues(new Uint8Array(16)));
      const payload = JSON.stringify({ u: username, t: issuedAt, n: nonce });
      const payloadB64 = b64url(new TextEncoder().encode(payload));
      const sig = await sign(payloadB64);
      const token = `${payloadB64}.${sig}`;

      return json(200, { token, expiresAt: expiresAt.toISOString() });
    }

    // GET /me
    if (method === "GET" && path === "/me") {
      const user = await auth(req);
      if (!user) return json(401, { error: "unauthorized" });
      return json(200, { username: user.username, role: user.role });
    }

    // GET /admin/stats
    if (method === "GET" && path === "/admin/stats") {
      const user = await auth(req);
      if (!user) return json(401, { error: "unauthorized" });
      if (user.role !== "admin") return json(403, { error: "forbidden" });
      const admins = users.filter((u) => u.role === "admin").length;
      return json(200, { users: users.length, admins });
    }

    // POST /logout
    if (method === "POST" && path === "/logout") {
      const user = await auth(req);
      if (!user) return json(401, { error: "unauthorized" });
      // Revoke the token
      const h = req.headers.get("Authorization");
      if (h && h.startsWith("Bearer ")) {
        revoked.add(h.slice(7));
      }
      return new Response(null, { status: 204 });
    }

    return json(404, { error: "not_found" });
  };
}
